<template>
  <div class="debug-page">
    <h1>API Debug Page</h1>
    
    <div class="debug-section">
      <h2>Endpoint Configuration</h2>
      <div class="form-group">
        <label for="endpoint">API Endpoint:</label>
        <input 
          id="endpoint" 
          v-model="endpoint" 
          type="text" 
          class="form-control"
          placeholder="https://00adylew20.execute-api.us-east-1.amazonaws.com/prod/formsubmission"
        />
      </div>
      
      <div class="form-group">
        <label for="authToken">Authorization Token:</label>
        <textarea 
          id="authToken" 
          v-model="authToken" 
          class="form-control"
          rows="3"
          placeholder="Bearer eyJraWQiOiJDajJxSmJyclwvYmdCSTd5cnVzXC9UaE5NbWpsSkhaQ25hcmQ1anFIUEJmQkk9..."
        ></textarea>
      </div>
    </div>

    <div class="debug-section">
      <h2>Form Data</h2>
      <div class="form-group">
        <label for="formData">Form Fields (JSON):</label>
        <textarea 
          id="formData" 
          v-model="formDataJson" 
          class="form-control"
          rows="6"
          placeholder='{"field1": "value1", "field2": "value2"}'
        ></textarea>
      </div>
      
      <div class="form-group">
        <label for="fileInput">File Upload:</label>
        <input 
          id="fileInput" 
          type="file" 
          @change="handleFileSelect"
          class="form-control"
        />
        <small v-if="selectedFile">Selected: {{ selectedFile.name }}</small>
      </div>
    </div>

    <div class="debug-section">
      <button @click="sendRequest" :disabled="isLoading" class="btn btn-primary">
        {{ isLoading ? 'Sending...' : 'Send Request' }}
      </button>
    </div>

    <div v-if="response" class="debug-section">
      <h2>Response</h2>
      <div class="response-info">
        <p><strong>Status:</strong> {{ response.status }} {{ response.statusText }}</p>
        <p><strong>Headers:</strong></p>
        <pre class="response-headers">{{ JSON.stringify(response.headers, null, 2) }}</pre>
        <p><strong>Body:</strong></p>
        <pre class="response-body">{{ response.data }}</pre>
      </div>
    </div>

    <div v-if="error" class="debug-section error">
      <h2>Error</h2>
      <pre class="error-message">{{ error }}</pre>
    </div>
  </div>
</template>

<script>
export default {
  name: 'DebugPage',
  data() {
    return {
      endpoint: 'https://00adylew20.execute-api.us-east-1.amazonaws.com/prod/formsubmission',
      authToken: '',
      formDataJson: '{"testField": "testValue"}',
      selectedFile: null,
      response: null,
      error: null,
      isLoading: false
    }
  },
  methods: {
    handleFileSelect(event) {
      this.selectedFile = event.target.files[0] || null;
    },
    
    async sendRequest() {
      this.isLoading = true;
      this.response = null;
      this.error = null;
      
      try {
        // Parse form data JSON
        let formDataObj = {};
        try {
          formDataObj = JSON.parse(this.formDataJson);
        } catch (e) {
          throw new Error('Invalid JSON in form data');
        }
        
        // Create FormData object
        const formData = new FormData();
        
        // Add form fields
        Object.keys(formDataObj).forEach(key => {
          formData.append(key, formDataObj[key]);
        });
        
        // Add file if selected
        if (this.selectedFile) {
          formData.append('file', this.selectedFile);
        }
        
        // Prepare headers
        const headers = {
          'Accept': 'application/json, text/plain, */*',
          'Content-Type': 'multipart/form-data'
        };
        
        // Add authorization header if provided
        if (this.authToken.trim()) {
          headers['Authorization'] = this.authToken.trim();
        }
        
        // Make the request
        const response = await fetch(this.endpoint, {
          method: 'POST',
          headers: headers,
          body: formData
        });
        
        // Parse response
        const responseData = await response.text();
        
        this.response = {
          status: response.status,
          statusText: response.statusText,
          headers: Object.fromEntries(response.headers.entries()),
          data: responseData
        };
        
      } catch (err) {
        this.error = err.message || 'An error occurred while making the request';
        console.error('Request error:', err);
      } finally {
        this.isLoading = false;
      }
    }
  }
}
</script>

